// List.copyOf — copia independiente
List<String> mutable = new ArrayList<>(List.of("X", "Y"));
List<String> copy = List.copyOf(mutable);
mutable.add("Z");
System.out.println(copy); // [X, Y] — no cambia

// Collections.unmodifiable — wrapper dependiente
List<String> wrapper = Collections.unmodifiableList(mutable);
mutable.add("W");
System.out.println(wrapper); // [X, Y, Z, W] — refleja cambios

// unmodifiable: wrapper dependiente de la original
List<String> original = new ArrayList<>(List.of("A", "B"));
List<String> unmod = Collections.unmodifiableList(original);
original.add("C");
System.out.println(unmod); // [A, B, C] — cambio!

// copyOf: copia independiente
List<String> original2 = new ArrayList<>(List.of("X", "Y"));
List<String> copied = List.copyOf(original2);
original2.add("Z");
System.out.println(copied); // [X, Y] — no cambio

// Intentar modificar copia inmutable lanza UnsupportedOperation
try {
    copied.add("W");
} catch (UnsupportedOperationException e) {
    System.out.println("No se puede modificar copia inmutable");
}

